      "name": "maxLines",
      "type": "number",
      "description": "Maximum number of lines to show before clamping with an ellipsis.",
      "required": true
    },
    {
      "name": "hasTruncateTooltip",
      "type": "boolean",
      "description": "Show a tooltip with the full text content on hover or keyboard focus when clamped. A clamped root is focusable (tabindex 0) so keyboard users can reach the tooltip; a tabIndex you pass wins. The tooltip props follow Text's: when Text's hasTruncateTooltip is renamed in a minor, LineClamp follows.",
      "default": "true"
    },
    {
      "name": "truncateTooltipPlacement",
      "type": "'above' | 'below' | 'start' | 'end'",
      "description": "Where the truncation tooltip opens.",
      "default": "'above'"
    },
    {
      "name": "as",
      "type": "'div' | 'span' | 'p'",
      "description": "HTML element to render.",
      "default": "'div'"
    }
  ],
